import { readFileSync } from 'node:fs';

export type Box = [number, number, number, number];
export interface SpatialObject {
  id: number;
  box: Box;
}
export interface Point extends SpatialObject {
  x: number;
  y: number;
}
export interface Settings {
  world: number;
  bucket: number;
  maximum: number;
  minimum: number;
  cell: number;
}
export interface Command {
  name: string;
  args: number[];
}
export function point(id: number, x: number, y: number): Point {
  return { id, x, y, box: [x, y, x, y] };
}
const lines = (name: string): string[] =>
  readFileSync('input/' + name, 'ascii')
    .trimEnd()
    .split('\n');
export function readDataset() {
  const points = lines('points.csv')
    .slice(1)
    .map((line) => {
      const [id, x, y] = line.split(',').map(Number);
      return point(id, x, y);
    });
  const rectangles: SpatialObject[] = lines('rects.csv')
    .slice(1)
    .map((line): SpatialObject => {
      const [id, x1, y1, x2, y2] = line.split(',').map(Number);
      return { id, box: [x1, y1, x2, y2] };
    });
  const params = lines('params.txt').map((line) => line.split(' ').slice(1).map(Number));
  const settings: Settings = {
    world: params[0][0],
    bucket: params[1][0],
    maximum: params[2][0],
    minimum: params[2][1],
    cell: params[3][0],
  };
  const commands: Command[] = lines('queries.txt').map((line) => {
    const [name, ...values] = line.split(' ');
    return { name, args: values.map(Number) };
  });
  return { points, rectangles, settings, commands };
}

import type { Point } from './dataset.ts';

export interface Cell {
  column: number;
  row: number;
  points: Point[];
}
export class Grid {
  side: number;
  cells: Cell[] = [];
  constructor(
    points: Point[],
    world: number,
    public size: number,
  ) {
    this.side = world / size;
    for (let row = 0; row < this.side; row++) {
      for (let column = 0; column < this.side; column++) {
        this.cells.push({ column, row, points: [] });
      }
    }
    for (const p of points) this.insert(p);
  }
  cell(point: Point): Cell {
    return this.cells[
      Math.floor(point.y / this.size) * this.side + Math.floor(point.x / this.size)
    ];
  }
  insert(point: Point): void {
    const cell = this.cell(point);
    cell.points.push(point);
    cell.points.sort((a, b) => a.id - b.id);
  }
  remove(point: Point): void {
    const cell = this.cell(point);
    cell.points.splice(
      cell.points.findIndex((p) => p.id === point.id),
      1,
    );
  }
}

import type { Point } from './dataset.ts';

export class KDNode {
  left: KDNode | null = null;
  right: KDNode | null = null;
  constructor(
    public point: Point,
    public axis: number,
  ) {}
}
export function compare(a: Point, b: Point, axis: number): number {
  return axis === 0 ? a.x - b.x || a.y - b.y || a.id - b.id : a.y - b.y || a.x - b.x || a.id - b.id;
}
function build(points: Point[], depth = 0): KDNode | null {
  if (!points.length) return null;
  const axis = depth % 2;
  const ordered = points.slice().sort((a, b) => compare(a, b, axis));
  const middle = Math.floor(ordered.length / 2);
  const node = new KDNode(ordered[middle], axis);
  node.left = build(ordered.slice(0, middle), depth + 1);
  node.right = build(ordered.slice(middle + 1), depth + 1);
  return node;
}
function minimum(node: KDNode, axis: number): Point {
  if (node.axis === axis) return node.left ? minimum(node.left, axis) : node.point;
  let best = node.point;
  for (const child of [node.left, node.right]) {
    if (child) {
      const p = minimum(child, axis);
      if (compare(p, best, axis) < 0) best = p;
    }
  }
  return best;
}
function remove(node: KDNode, point: Point): KDNode | null {
  if (node.point.id === point.id) {
    if (node.right) {
      node.point = minimum(node.right, node.axis);
      node.right = remove(node.right, node.point);
    } else if (node.left) {
      node.point = minimum(node.left, node.axis);
      node.right = remove(node.left, node.point);
      node.left = null;
    } else return null;
  } else if (compare(point, node.point, node.axis) < 0) node.left = remove(node.left!, point);
  else node.right = remove(node.right!, point);
  return node;
}
export class KDTree {
  root: KDNode | null;
  constructor(points: Point[]) {
    this.root = build(points);
  }
  insert(point: Point): void {
    if (!this.root) {
      this.root = new KDNode(point, 0);
      return;
    }
    let node = this.root;
    for (;;) {
      const side = compare(point, node.point, node.axis) < 0 ? 'left' : 'right';
      const child = node[side];
      if (!child) {
        node[side] = new KDNode(point, 1 - node.axis);
        return;
      }
      node = child;
    }
  }
  remove(point: Point): void {
    this.root = remove(this.root!, point);
  }
}

import { mkdirSync } from 'node:fs';
import {
  readDataset,
  point,
  type Point,
  type SpatialObject,
  type Box,
  type Settings,
} from './dataset.ts';
import { KDTree, KDNode, compare as compareKD } from './kdtree.ts';
import { QuadTree, QuadNode, destination, NAMES } from './quadtree.ts';
import { RTree, RNode, box, contains, intersects, compare, area, overlap } from './rtree.ts';
import { Grid } from './grid.ts';
import { fraction, ids, writeLines } from './report.ts';

const POINT_NAMES = ['kdtree', 'quadtree', 'rtree', 'str', 'grid'] as const;
const RECT_NAMES = ['rtree_rect', 'str_rect'] as const;
const R_NAMES = ['rtree', 'str', ...RECT_NAMES] as const;
const TREE_NAMES = ['kdtree', 'quadtree', ...R_NAMES] as const;
type Structure = (typeof POINT_NAMES)[number] | (typeof RECT_NAMES)[number];
const SEARCHES = ['RANGE', 'RADIUS', 'KNN', 'WINDOWCOUNT', 'CONTAINS', 'NEAREST', 'JOIN'];
type Pair = [number, number];
type Answer =
  | { kind: 'ids'; values: number[] }
  | { kind: 'pairs'; values: Pair[] }
  | { kind: 'count'; value: number };
interface SearchResult {
  answer: Answer;
  nodes: number;
  tests: number;
}
interface View {
  region: Box;
  held: SpatialObject[];
  children: View[];
  count: number;
  depth: number;
  line: string;
  level: number;
  entries: number;
}
interface Totals {
  queries: number;
  nodes: number;
  tests: number;
  maximum: number;
}
interface State {
  settings: Settings;
  points: Map<number, Point>;
  rectangles: SpatialObject[];
  structures: {
    kdtree: KDTree;
    quadtree: QuadTree;
    rtree: RTree;
    str: RTree;
    grid: Grid;
    rtree_rect: RTree;
    str_rect: RTree;
  };
  snapshots: number;
  answers: string[];
  visits: string[];
  joins: string[];
  dumps: string[];
  statistics: string[];
  totals: Map<string, Map<Structure, Totals>>;
}
const fields = (...values: (number | string)[]): string => values.join(' ');
function minimumDistance(x: number, y: number, b: Box): number {
  const dx = x < b[0] ? b[0] - x : x > b[2] ? x - b[2] : 0;
  const dy = y < b[1] ? b[1] - y : y > b[3] ? y - b[3] : 0;
  return dx * dx + dy * dy;
}
const bounds = (args: number[]): Box => [args[0], args[1], args[2], args[3]];
function makeView(
  region: Box,
  held: SpatialObject[],
  children: View[],
  depth: number,
  line: string,
  level = 0,
  entries = 0,
): View {
  return {
    region,
    held,
    children,
    depth,
    line,
    level,
    entries,
    count: held.length + children.reduce((n, c) => n + c.count, 0),
  };
}
function kdView(node: KDNode, region: Box, depth = 0, mark = 'root'): View {
  const children: View[] = [];
  const split = node.axis === 0 ? node.point.x : node.point.y;
  if (node.left) {
    const b: Box = [...region];
    b[node.axis + 2] = split;
    children.push(kdView(node.left, b, depth + 1, 'L'));
  }
  if (node.right) {
    const b: Box = [...region];
    b[node.axis] = split;
    children.push(kdView(node.right, b, depth + 1, 'R'));
  }
  return makeView(
    region,
    [node.point],
    children,
    depth,
    fields(
      mark,
      node.axis === 0 ? 'x' : 'y',
      node.point.id,
      node.point.x,
      node.point.y,
      'box',
      ...region,
    ),
  );
}
function quadView(node: QuadNode, depth = 0, mark = 'root'): View {
  const region: Box = [node.x, node.y, node.x + node.size - 1, node.y + node.size - 1];
  const children = node.children
    ? node.children.map((child, i) => quadView(child, depth + 1, NAMES[i]))
    : [];
  const view = makeView(region, node.points, children, depth, '');
  view.line = fields(
    mark,
    node.x,
    node.y,
    node.size,
    node.children ? `node count ${view.count}` : `leaf ${ids(node.points.map((p) => p.id))}`,
  );
  return view;
}
function rtreeView(node: RNode, depth = 0): View {
  const children = node.level > 0 ? node.entries.map((e) => rtreeView(e.child!, depth + 1)) : [];
  const held = node.level === 0 ? node.entries.map((e) => e.object!) : [];
  const region = box(node);
  const line =
    node.level === 0
      ? fields('leaf', ...region, 'ids', ids(held.map((o) => o.id)))
      : fields('node', node.level, ...region, 'entries', node.entries.length);
  return makeView(region, held, children, depth, line, node.level, node.entries.length);
}
function currentViews(state: State): Record<Structure, View> {
  const { world } = state.settings;
  const s = state.structures;
  const cells = s.grid.cells.map((cell) => {
    const x = cell.column * s.grid.size;
    const y = cell.row * s.grid.size;
    return makeView([x, y, x + s.grid.size - 1, y + s.grid.size - 1], cell.points, [], 1, '');
  });
  return {
    kdtree: kdView(s.kdtree.root!, [0, 0, world - 1, world - 1]),
    quadtree: quadView(s.quadtree.root),
    rtree: rtreeView(s.rtree.root),
    str: rtreeView(s.str.root),
    rtree_rect: rtreeView(s.rtree_rect.root),
    str_rect: rtreeView(s.str_rect.root),
    grid: makeView([0, 0, world - 1, world - 1], [], cells, 0, ''),
  };
}
function conditionSearch(
  root: View,
  regionCondition: (box: Box) => boolean,
  objectCondition: (object: SpatialObject) => boolean,
): SearchResult {
  const answer: number[] = [];
  const pending = [root];
  let nodes = 0;
  let tests = 0;
  while (pending.length) {
    const node = pending.pop()!;
    nodes++;
    tests += node.held.length;
    for (const object of node.held) if (objectCondition(object)) answer.push(object.id);
    for (let i = node.children.length - 1; i >= 0; i--) {
      if (regionCondition(node.children[i].region)) pending.push(node.children[i]);
    }
  }
  answer.sort((a, b) => a - b);
  return { answer: { kind: 'ids', values: answer }, nodes, tests };
}
function windowCount(root: View, window: Box): SearchResult {
  let answer = 0;
  let nodes = 0;
  let tests = 0;
  const pending = [root];
  while (pending.length) {
    const node = pending.pop()!;
    nodes++;
    if (contains(window, node.region)) {
      answer += node.count;
      continue;
    }
    tests += node.held.length;
    for (const object of node.held) if (contains(window, object.box)) answer++;
    for (let i = node.children.length - 1; i >= 0; i--) {
      if (intersects(node.children[i].region, window)) pending.push(node.children[i]);
    }
  }
  return { answer: { kind: 'count', value: answer }, nodes, tests };
}
type QueueEntry =
  | { key: [number, number, number]; kind: 'node'; node: View }
  | { key: [number, number, number]; kind: 'object'; object: SpatialObject };
class PriorityQueue {
  private entries: QueueEntry[] = [];
  push(entry: QueueEntry): void {
    let i = this.entries.length;
    this.entries.push(entry);
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (compare(this.entries[parent].key, entry.key) < 0) break;
      this.entries[i] = this.entries[parent];
      i = parent;
    }
    this.entries[i] = entry;
  }
  pop(): QueueEntry {
    const first = this.entries[0];
    const last = this.entries.pop()!;
    if (!this.entries.length) return first;
    let i = 0;
    while (2 * i + 1 < this.entries.length) {
      let child = 2 * i + 1;
      if (
        child + 1 < this.entries.length &&
        compare(this.entries[child + 1].key, this.entries[child].key) < 0
      ) {
        child++;
      }
      if (compare(last.key, this.entries[child].key) < 0) break;
      this.entries[i] = this.entries[child];
      i = child;
    }
    this.entries[i] = last;
    return first;
  }
}
function nearestSearch(root: View, x: number, y: number, count: number): SearchResult {
  const pending = new PriorityQueue();
  const answer: Pair[] = [];
  let serial = 0;
  let nodes = 0;
  let tests = 0;
  const enqueue = (node: View): void =>
    pending.push({ key: [minimumDistance(x, y, node.region), 0, serial++], kind: 'node', node });
  enqueue(root);
  while (answer.length < count) {
    const entry = pending.pop();
    if (entry.kind === 'object') {
      answer.push([entry.object.id, entry.key[0]]);
      continue;
    }
    const node = entry.node;
    nodes++;
    tests += node.held.length;
    for (const object of node.held) {
      pending.push({
        key: [minimumDistance(x, y, object.box), 1, object.id],
        kind: 'object',
        object,
      });
    }
    for (const child of node.children) enqueue(child);
  }
  return { answer: { kind: 'pairs', values: answer }, nodes, tests };
}
function spatialJoin(pointRoot: View, rectangleRoot: View): SearchResult {
  const answer: Pair[] = [];
  let nodes = 0;
  let tests = 0;
  function visit(a: View, b: View): void {
    nodes++;
    if (!a.children.length && !b.children.length) {
      tests += a.held.length * b.held.length;
      for (const p of a.held) {
        for (const r of b.held) if (contains(r.box, p.box)) answer.push([r.id, p.id]);
      }
    } else if (!a.children.length) {
      for (const child of b.children) if (intersects(child.region, a.region)) visit(a, child);
    } else if (!b.children.length) {
      for (const child of a.children) if (intersects(child.region, b.region)) visit(child, b);
    } else {
      for (const p of a.children) {
        for (const r of b.children) if (intersects(p.region, r.region)) visit(p, r);
      }
    }
  }
  visit(pointRoot, rectangleRoot);
  answer.sort(compare);
  return { answer: { kind: 'pairs', values: answer }, nodes, tests };
}
function searchNames(command: string): readonly Structure[] {
  return command === 'JOIN'
    ? ['rtree', 'str']
    : command === 'CONTAINS' || command === 'NEAREST'
      ? RECT_NAMES
      : POINT_NAMES;
}
function search(root: View, command: string, args: number[]): SearchResult {
  const [x, y] = args;
  const q: Box = [x, y, x, y];
  if (command === 'RANGE') {
    const b = bounds(args);
    return conditionSearch(
      root,
      (r) => intersects(r, b),
      (o) => contains(b, o.box),
    );
  }
  if (command === 'RADIUS') {
    const r2 = args[2] * args[2];
    return conditionSearch(
      root,
      (b) => minimumDistance(x, y, b) <= r2,
      (o) => minimumDistance(x, y, o.box) <= r2,
    );
  }
  if (command === 'CONTAINS') {
    return conditionSearch(
      root,
      (b) => contains(b, q),
      (o) => contains(o.box, q),
    );
  }
  if (command === 'WINDOWCOUNT') return windowCount(root, bounds(args));
  return nearestSearch(root, x, y, args[2]);
}
function bruteForce(state: State, command: string, args: number[]): Answer {
  const points = [...state.points.values()].sort((a, b) => a.id - b.id);
  const [x, y] = args;
  if (command === 'JOIN') {
    const pairs: Pair[] = [];
    for (const r of state.rectangles) {
      for (const p of points) if (contains(r.box, p.box)) pairs.push([r.id, p.id]);
    }
    return { kind: 'pairs', values: pairs };
  }
  if (command === 'KNN' || command === 'NEAREST') {
    const objects = command === 'KNN' ? points : state.rectangles;
    const values = objects.map((o): Pair => [o.id, minimumDistance(x, y, o.box)]);
    values.sort((a, b) => a[1] - b[1] || a[0] - b[0]);
    return { kind: 'pairs', values: values.slice(0, args[2]) };
  }
  const values =
    command === 'CONTAINS'
      ? state.rectangles.filter((r) => contains(r.box, [x, y, x, y])).map((r) => r.id)
      : points
          .filter((p) =>
            command === 'RADIUS'
              ? minimumDistance(x, y, p.box) <= args[2] * args[2]
              : contains(bounds(args), p.box),
          )
          .map((p) => p.id);
  return command === 'WINDOWCOUNT'
    ? { kind: 'count', value: values.length }
    : { kind: 'ids', values };
}
function recordVisit(
  state: State,
  query: number,
  command: string,
  name: Structure,
  result: SearchResult,
): void {
  state.visits.push([query, command, name, result.nodes, result.tests].join(','));
  if (!state.totals.has(command)) state.totals.set(command, new Map());
  const totals = state.totals.get(command)!;
  if (!totals.has(name)) totals.set(name, { queries: 0, nodes: 0, tests: 0, maximum: 0 });
  const t = totals.get(name)!;
  t.queries++;
  t.nodes += result.nodes;
  t.tests += result.tests;
  t.maximum = Math.max(t.maximum, result.nodes);
}
function executeSearch(state: State, query: number, command: string, args: number[]): string {
  const expected = bruteForce(state, command, args);
  const views = currentViews(state);
  const mismatches: Structure[] = [];
  for (const name of searchNames(command)) {
    const result =
      command === 'JOIN'
        ? spatialJoin(views[name], name === 'rtree' ? views.rtree_rect : views.str_rect)
        : search(views[name], command, args);
    recordVisit(state, query, command, name, result);
    if (JSON.stringify(result.answer) !== JSON.stringify(expected)) mismatches.push(name);
  }
  const check = mismatches.length ? 'mismatch ' + mismatches.join(' ') : 'ok';
  if (expected.kind === 'count') {
    return fields(query, command, 'count', expected.value, 'check', check);
  }
  if (command === 'JOIN' && expected.kind === 'pairs') {
    for (const pair of expected.values) state.joins.push([query, ...pair].join(','));
    return fields(query, command, 'count', expected.values.length, 'check', check);
  }
  const values =
    expected.kind === 'pairs' ? expected.values.map((pair) => pair.join(':')) : expected.values;
  return fields(query, command, 'count', values.length, 'ids', ids(values), 'check', check);
}
function preorder(root: View): View[] {
  const nodes: View[] = [];
  const pending = [root];
  while (pending.length) {
    const node = pending.pop()!;
    nodes.push(node);
    for (let i = node.children.length - 1; i >= 0; i--) pending.push(node.children[i]);
  }
  return nodes;
}
function kdStatistics(root: View): string[] {
  const nodes = preorder(root);
  const depths: { nodes: number; leaves: number; oneChild: number }[] = [];
  let leaves = 0;
  let oneChild = 0;
  let depthSum = 0;
  for (const node of nodes) {
    while (depths.length <= node.depth) depths.push({ nodes: 0, leaves: 0, oneChild: 0 });
    const d = depths[node.depth];
    d.nodes++;
    depthSum += node.depth;
    if (!node.children.length) {
      d.leaves++;
      leaves++;
    } else if (node.children.length === 1) {
      d.oneChild++;
      oneChild++;
    }
  }
  let ideal = 0;
  while (2 ** ideal - 1 < nodes.length) ideal++;
  return [
    fields(
      'kdtree height',
      depths.length,
      'ideal',
      ideal,
      'nodes',
      nodes.length,
      'leaves',
      leaves,
      'one_child',
      oneChild,
      'depth_sum',
      depthSum,
      'avg_depth',
      fraction(depthSum, nodes.length),
    ),
    ...depths.map(
      (d, t) =>
        '  ' + fields('depth', t, 'nodes', d.nodes, 'leaves', d.leaves, 'one_child', d.oneChild),
    ),
  ];
}
function quadStatistics(root: View, bucket: number): string[] {
  const depths: { internal: number; leaves: number; points: number }[] = [];
  let internal = 0;
  let leaves = 0;
  let empty = 0;
  let maximum = 0;
  for (const node of preorder(root)) {
    while (depths.length <= node.depth) depths.push({ internal: 0, leaves: 0, points: 0 });
    const d = depths[node.depth];
    if (node.children.length) {
      d.internal++;
      internal++;
    } else {
      d.leaves++;
      d.points += node.held.length;
      leaves++;
      if (!node.held.length) empty++;
      maximum = Math.max(maximum, node.held.length);
    }
  }
  return [
    fields(
      'quadtree height',
      depths.length,
      'internal',
      internal,
      'leaves',
      leaves,
      'empty',
      empty,
      'max_leaf',
      maximum,
      'fill',
      fraction(root.count, leaves * bucket),
    ),
    ...depths.map(
      (d, t) =>
        '  ' + fields('depth', t, 'internal', d.internal, 'leaves', d.leaves, 'points', d.points),
    ),
  ];
}
function rtreeStatistics(name: string, root: View, settings: Settings): string[] {
  const nodes = preorder(root);
  const height = root.level + 1;
  const levels: View[][] = Array.from({ length: height }, () => []);
  let leaves = 0;
  let entries = 0;
  for (const node of nodes) {
    levels[node.level].push(node);
    entries += node.entries;
    if (node.level === 0) leaves++;
  }
  const lines = [
    fields(
      name,
      'height',
      height,
      'nodes',
      nodes.length,
      'leaves',
      leaves,
      'entries',
      entries,
      'fill',
      fraction(entries, nodes.length * settings.maximum),
    ),
  ];
  for (let level = height - 1; level >= 0; level--) {
    const group = levels[level];
    let total = 0;
    let minimum = Infinity;
    let maximum = 0;
    let under = 0;
    let totalArea = 0;
    let totalOverlap = 0;
    for (let i = 0; i < group.length; i++) {
      const node = group[i];
      total += node.entries;
      minimum = Math.min(minimum, node.entries);
      maximum = Math.max(maximum, node.entries);
      if (node.entries < settings.minimum) under++;
      totalArea += area(node.region);
      for (let j = i + 1; j < group.length; j++) {
        totalOverlap += overlap(node.region, group[j].region);
      }
    }
    lines.push(
      '  ' +
        fields(
          'level',
          level,
          'nodes',
          group.length,
          'entries',
          total,
          'min',
          minimum,
          'max',
          maximum,
          'under',
          under,
          'area',
          totalArea,
          'overlap',
          totalOverlap,
        ),
    );
  }
  return lines;
}
function gridStatistics(root: View): string[] {
  const occupancy = new Map<number, number>();
  let used = 0;
  let maximum = 0;
  for (const cell of root.children) {
    const count = cell.held.length;
    occupancy.set(count, (occupancy.get(count) ?? 0) + 1);
    if (count) used++;
    maximum = Math.max(maximum, count);
  }
  return [
    fields('grid cells', root.children.length, 'used', used, 'max', maximum),
    '  occupancy ' +
      [...occupancy]
        .sort((a, b) => a[0] - b[0])
        .map((pair) => pair.join(':'))
        .join(' '),
  ];
}
function snapshot(state: State, query: number): number {
  const number = state.snapshots++;
  const views = currentViews(state);
  const header = fields(
    'snapshot',
    number,
    'query',
    query,
    'points',
    state.points.size,
    'rects',
    state.rectangles.length,
  );
  if (number > 0) {
    state.dumps.push('');
    state.statistics.push('');
  }
  state.dumps.push(header);
  state.statistics.push(header);
  for (const name of TREE_NAMES) {
    state.dumps.push(
      name,
      ...preorder(views[name]).map((v) => ' '.repeat(2 * (v.depth + 1)) + v.line),
    );
  }
  state.statistics.push(
    ...kdStatistics(views.kdtree),
    ...quadStatistics(views.quadtree, state.settings.bucket),
  );
  for (const name of R_NAMES) {
    state.statistics.push(...rtreeStatistics(name, views[name], state.settings));
  }
  state.statistics.push(...gridStatistics(views.grid));
  return number;
}
function locateKD(root: KDNode, point: Point): string {
  let node = root;
  let path = '';
  while (node.point.id !== point.id) {
    const left = compareKD(point, node.point, node.axis) < 0;
    path += left ? 'L' : 'R';
    node = left ? node.left! : node.right!;
  }
  return path || '-';
}
function locateQuad(root: QuadNode, point: Point): string {
  let node = root;
  const path: string[] = [];
  while (node.children) {
    const child = destination(node, point);
    path.push(NAMES[child]);
    node = node.children[child];
  }
  return path.join('/') || '-';
}
function locateRTree(node: RNode, point: Point): number[] | null {
  if (node.level === 0) {
    const index = node.entries.findIndex((e) => e.object!.id === point.id);
    return index < 0 ? null : [index + 1];
  }
  for (let i = 0; i < node.entries.length; i++) {
    if (contains(node.entries[i].box, point.box)) {
      const found = locateRTree(node.entries[i].child!, point);
      if (found) return [i + 1, ...found];
    }
  }
  return null;
}
function locate(state: State, query: number, id: number): string {
  const p = state.points.get(id);
  if (!p) return fields(query, 'LOCATE', id, 'missing');
  const s = state.structures;
  const cell = s.grid.cell(p);
  return fields(
    query,
    'LOCATE',
    id,
    'kdtree',
    locateKD(s.kdtree.root!, p),
    'quadtree',
    locateQuad(s.quadtree.root, p),
    'rtree',
    locateRTree(s.rtree.root, p)!.join('/'),
    'str',
    locateRTree(s.str.root, p)!.join('/'),
    'grid',
    cell.column,
    cell.row,
  );
}
function updatePoint(state: State, query: number, command: string, args: number[]): string {
  const id = args[0];
  if (command === 'INSERT') {
    const p = point(id, args[1], args[2]);
    for (const name of POINT_NAMES) state.structures[name].insert(p);
    state.points.set(id, p);
    return fields(query, command, id, 'inserted points', state.points.size);
  }
  const p = state.points.get(id);
  if (!p) return fields(query, command, id, 'missing points', state.points.size);
  for (const name of POINT_NAMES) state.structures[name].remove(p);
  state.points.delete(id);
  return fields(query, command, id, 'deleted points', state.points.size);
}
function visitSummary(state: State): string[] {
  const lines = ['visits'];
  for (const command of SEARCHES) {
    const totals = state.totals.get(command);
    if (!totals) continue;
    const names = searchNames(command);
    for (const name of names) {
      const t = totals.get(name)!;
      lines.push(
        fields(
          command,
          name,
          'queries',
          t.queries,
          'nodes',
          t.nodes,
          'tests',
          t.tests,
          'max_nodes',
          t.maximum,
          'mean_nodes',
          fraction(t.nodes, t.queries),
        ),
      );
    }
    const ranking = names
      .map((name, i) => ({ name, i, ...totals.get(name)! }))
      .sort((a, b) => a.nodes - b.nodes || a.tests - b.tests || a.i - b.i);
    lines.push(fields('rank', command, ...ranking.map((r) => r.name)));
  }
  return lines;
}
function initialize(data: ReturnType<typeof readDataset>): State {
  const { points, rectangles, settings: p } = data;
  return {
    settings: p,
    points: new Map(points.map((p) => [p.id, p])),
    rectangles: rectangles.slice().sort((a, b) => a.id - b.id),
    structures: {
      kdtree: new KDTree(points),
      quadtree: new QuadTree(points, p.world, p.bucket),
      grid: new Grid(points, p.world, p.cell),
      rtree: new RTree(points, p.maximum, p.minimum),
      str: new RTree(points, p.maximum, p.minimum, true),
      rtree_rect: new RTree(rectangles, p.maximum, p.minimum),
      str_rect: new RTree(rectangles, p.maximum, p.minimum, true),
    },
    snapshots: 0,
    answers: [],
    visits: ['query,command,structure,nodes,tests'],
    joins: ['query,rect,point'],
    dumps: [],
    statistics: [],
    totals: new Map(),
  };
}
function main(): void {
  const data = readDataset();
  const state = initialize(data);
  snapshot(state, 0);
  data.commands.forEach(({ name, args }, i) => {
    const query = i + 1;
    state.answers.push(
      SEARCHES.includes(name)
        ? executeSearch(state, query, name, args)
        : name === 'LOCATE'
          ? locate(state, query, args[0])
          : name === 'DUMP'
            ? fields(query, 'DUMP snapshot', snapshot(state, query))
            : updatePoint(state, query, name, args),
    );
  });
  state.statistics.push('', ...visitSummary(state));
  mkdirSync('output', { recursive: true });
  for (const [name, lines] of [
    ['answers.txt', state.answers],
    ['visits.csv', state.visits],
    ['join.csv', state.joins],
    ['structures.txt', state.dumps],
    ['stats.txt', state.statistics],
  ] satisfies [string, string[]][]) {
    writeLines(name, lines);
  }
}
main();

import type { Point } from './dataset.ts';

export const NAMES = ['NW', 'NE', 'SW', 'SE'];
export class QuadNode {
  points: Point[] = [];
  children: QuadNode[] | null = null;
  constructor(
    public x: number,
    public y: number,
    public size: number,
  ) {}
}
export function destination(node: QuadNode, point: Point): number {
  const half = node.size / 2;
  return Number(point.x >= node.x + half) + 2 * Number(point.y >= node.y + half);
}
function insert(node: QuadNode, point: Point, bucket: number): void {
  if (node.children) {
    insert(node.children[destination(node, point)], point, bucket);
    return;
  }
  node.points.push(point);
  node.points.sort((a, b) => a.id - b.id);
  if (node.points.length <= bucket) return;
  const h = node.size / 2;
  node.children = [
    new QuadNode(node.x, node.y, h),
    new QuadNode(node.x + h, node.y, h),
    new QuadNode(node.x, node.y + h, h),
    new QuadNode(node.x + h, node.y + h, h),
  ];
  const previous = node.points;
  node.points = [];
  for (const held of previous) insert(node, held, bucket);
}
function remove(node: QuadNode, point: Point, bucket: number): void {
  if (!node.children) {
    node.points.splice(
      node.points.findIndex((p) => p.id === point.id),
      1,
    );
    return;
  }
  remove(node.children[destination(node, point)], point, bucket);
  if (node.children.some((child) => child.children)) return;
  const points = node.children.flatMap((child) => child.points);
  if (points.length <= bucket) {
    node.points = points.sort((a, b) => a.id - b.id);
    node.children = null;
  }
}
export class QuadTree {
  root: QuadNode;
  constructor(
    points: Point[],
    world: number,
    private bucket: number,
  ) {
    this.root = new QuadNode(0, 0, world);
    for (const p of points) this.insert(p);
  }
  insert(point: Point): void {
    insert(this.root, point, this.bucket);
  }
  remove(point: Point): void {
    remove(this.root, point, this.bucket);
  }
}

import { writeFileSync } from 'node:fs';

export function fraction(numerator: number, denominator: number): string {
  let a = numerator;
  let b = denominator;
  while (b !== 0) [a, b] = [b, a % b];
  return `${numerator / a}/${denominator / a}`;
}
export const ids = (values: readonly (number | string)[]): string =>
  values.length ? values.join(' ') : '-';
export function writeLines(filename: string, lines: string[]): void {
  writeFileSync('output/' + filename, lines.length ? lines.join('\n') + '\n' : '', 'ascii');
}

import type { Box, SpatialObject } from './dataset.ts';

export const area = (b: Box): number => (b[2] - b[0]) * (b[3] - b[1]);
export const union = (a: Box, b: Box): Box => [
  Math.min(a[0], b[0]),
  Math.min(a[1], b[1]),
  Math.max(a[2], b[2]),
  Math.max(a[3], b[3]),
];
export const enlargement = (a: Box, b: Box): number => area(union(a, b)) - area(a);
export const contains = (a: Box, b: Box): boolean =>
  a[0] <= b[0] && b[2] <= a[2] && a[1] <= b[1] && b[3] <= a[3];
export const intersects = (a: Box, b: Box): boolean =>
  a[0] <= b[2] && b[0] <= a[2] && a[1] <= b[3] && b[1] <= a[3];
export function overlap(a: Box, b: Box): number {
  const w = Math.min(a[2], b[2]) - Math.max(a[0], b[0]);
  const h = Math.min(a[3], b[3]) - Math.max(a[1], b[1]);
  return w > 0 && h > 0 ? w * h : 0;
}
export function compare(a: readonly number[], b: readonly number[]): number {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] - b[i];
  return 0;
}
export interface Entry {
  box: Box;
  object?: SpatialObject;
  child?: RNode;
}
export class RNode {
  parent: RNode | null = null;
  constructor(
    public level: number,
    public entries: Entry[] = [],
  ) {
    for (const e of entries) if (e.child) e.child.parent = this;
  }
}
export function box(node: RNode): Box {
  let result = node.entries[0].box;
  for (let i = 1; i < node.entries.length; i++) result = union(result, node.entries[i].box);
  return result;
}
const leafEntry = (object: SpatialObject): Entry => ({ box: object.box, object });
const childEntry = (child: RNode): Entry => ({ box: box(child), child });
function split(node: RNode, minimum: number): RNode {
  const entries = node.entries;
  let first = 0;
  let second = 1;
  let waste = -Infinity;
  for (let i = 0; i < entries.length - 1; i++) {
    for (let j = i + 1; j < entries.length; j++) {
      const w =
        area(union(entries[i].box, entries[j].box)) - area(entries[i].box) - area(entries[j].box);
      if (w > waste) {
        waste = w;
        first = i;
        second = j;
      }
    }
  }
  const groups = [[entries[first]], [entries[second]]];
  const bounds = groups.map((g) => g[0].box);
  const rest = entries.filter((_, i) => i !== first && i !== second);
  while (rest.length) {
    if (groups[0].length + rest.length === minimum) {
      groups[0].push(...rest);
      break;
    }
    if (groups[1].length + rest.length === minimum) {
      groups[1].push(...rest);
      break;
    }
    let chosen = 0;
    let largest = -1;
    for (let i = 0; i < rest.length; i++) {
      const d = Math.abs(enlargement(bounds[0], rest[i].box) - enlargement(bounds[1], rest[i].box));
      if (d > largest) {
        largest = d;
        chosen = i;
      }
    }
    const [entry] = rest.splice(chosen, 1);
    const priorities = groups.map((g, i) => [
      enlargement(bounds[i], entry.box),
      area(bounds[i]),
      g.length,
    ]);
    const target = compare(priorities[0], priorities[1]) <= 0 ? 0 : 1;
    groups[target].push(entry);
    bounds[target] = union(bounds[target], entry.box);
  }
  node.entries = groups[0];
  for (const e of node.entries) if (e.child) e.child.parent = node;
  return new RNode(node.level, groups[1]);
}
function bulkLoad(objects: SpatialObject[], maximum: number): RNode {
  let entries: (Entry & { number: number })[] = objects.map((object) => ({
    ...leafEntry(object),
    number: object.id,
  }));
  let level = 0;
  for (;;) {
    const pages = Math.ceil(entries.length / maximum);
    let slabs = 1;
    while (slabs * slabs < pages) slabs++;
    entries.sort((a, b) =>
      compare(
        [a.box[0] + a.box[2], a.box[1] + a.box[3], a.number],
        [b.box[0] + b.box[2], b.box[1] + b.box[3], b.number],
      ),
    );
    const nodes: RNode[] = [];
    for (let start = 0; start < entries.length; start += slabs * maximum) {
      const slab = entries
        .slice(start, start + slabs * maximum)
        .sort((a, b) =>
          compare(
            [a.box[1] + a.box[3], a.box[0] + a.box[2], a.number],
            [b.box[1] + b.box[3], b.box[0] + b.box[2], b.number],
          ),
        );
      for (let offset = 0; offset < slab.length; offset += maximum) {
        nodes.push(new RNode(level, slab.slice(offset, offset + maximum)));
      }
    }
    if (nodes.length === 1) return nodes[0];
    entries = nodes.map((node, number) => ({ ...childEntry(node), number }));
    level++;
  }
}
function findLeaf(node: RNode, object: SpatialObject): { node: RNode; index: number } | null {
  if (node.level === 0) {
    const index = node.entries.findIndex((e) => e.object!.id === object.id);
    return index < 0 ? null : { node, index };
  }
  for (const e of node.entries) {
    if (contains(e.box, object.box)) {
      const found = findLeaf(e.child!, object);
      if (found) return found;
    }
  }
  return null;
}
export class RTree {
  root: RNode;
  constructor(
    objects: SpatialObject[],
    private maximum: number,
    private minimum: number,
    bulk = false,
  ) {
    this.root = bulk ? bulkLoad(objects, maximum) : new RNode(0);
    if (!bulk) for (const object of objects) this.insert(object);
  }
  private choose(entry: Entry, level: number): RNode {
    let node = this.root;
    while (node.level > level) {
      let selected = 0;
      let priority = [enlargement(node.entries[0].box, entry.box), area(node.entries[0].box)];
      for (let i = 1; i < node.entries.length; i++) {
        const p = [enlargement(node.entries[i].box, entry.box), area(node.entries[i].box)];
        if (compare(p, priority) < 0) {
          selected = i;
          priority = p;
        }
      }
      node = node.entries[selected].child!;
    }
    return node;
  }
  private insertEntry(entry: Entry, level: number): void {
    let node = this.choose(entry, level);
    node.entries.push(entry);
    if (entry.child) entry.child.parent = node;
    for (;;) {
      const sibling = node.entries.length > this.maximum ? split(node, this.minimum) : null;
      if (node === this.root) {
        if (sibling) this.root = new RNode(node.level + 1, [childEntry(node), childEntry(sibling)]);
        return;
      }
      const parent = node.parent!;
      parent.entries.find((e) => e.child === node)!.box = box(node);
      if (sibling) {
        parent.entries.push(childEntry(sibling));
        sibling.parent = parent;
      }
      node = parent;
    }
  }
  insert(object: SpatialObject): void {
    this.insertEntry(leafEntry(object), 0);
  }
  remove(object: SpatialObject): void {
    const found = findLeaf(this.root, object)!;
    found.node.entries.splice(found.index, 1);
    let node = found.node;
    const removed: RNode[] = [];
    while (node !== this.root) {
      const parent = node.parent!;
      const index = parent.entries.findIndex((e) => e.child === node);
      if (node.entries.length < this.minimum) {
        parent.entries.splice(index, 1);
        removed.push(node);
        node.parent = null;
      } else parent.entries[index].box = box(node);
      node = parent;
    }
    for (const detached of removed) {
      for (const e of detached.entries) this.insertEntry(e, detached.level);
    }
    while (this.root.level > 0 && this.root.entries.length === 1) {
      this.root = this.root.entries[0].child!;
      this.root.parent = null;
    }
  }
}
